        @Override public void onPageFinished(WebView v,String url){if(destroyed||nativeMode||url.equals("about:blank"))return;loading.setVisibility(View.GONE);if(yummyFrame)status.setText("Iframe · YummyAnime · серия "+number(wantedEpisode));}
