    private boolean allowedNavigation(Uri target){if(target.toString().startsWith(YummyFrame.BASE))return true;String host=target.getHost();if(host==null)return false;host=host.toLowerCase(Locale.ROOT);String original=Uri.parse(currentUrl).getHost();if(host.equals(original))return true;String[] suffixes={"kodikplayer.com","kodik.info","kodikres.com","stravers.live","ortified.ws","obrut.show","tazaromikaz.link","geralovod.link","factorios.live","horsez.org","ylitron.pro","yani.tv","yummyani.me","animego.me","animego.org","animego.one","aksor.tv","aksor.yani.tv","alloha.yani.tv","aniboom.one","sibnet.ru","video.sibnet.ru","vk.com","vkvideo.ru","video1.anilib.me","video2.anilib.me","sovetromantica.com"};for(String h:suffixes)if(host.equals(h)||host.endsWith("."+h))return true;return false;}
    private final class PlaybackBridge {@JavascriptInterface public void onEvent(String payload){if(payload==null||payload.length()>3000||destroyed||!yummyFrame)return;try{JSONObject j=new JSONObject(payload);final String nonce=j.optString("n");if(!bridgeNonce.equals(nonce))return;final String kind=j.optString("kind");if(kind.equals("ready")){YoruApp.app().main.post(()->{if(!destroyed&&yummyFrame&&bridgeNonce.equals(nonce)){loading.setVisibility(View.GONE);status.setText("Iframe · YummyAnime · серия "+number(wantedEpisode));}});return;}if(!trustedKodik)return;if(kind.equals("state")){boolean active=j.optBoolean("playing");YoruApp.app().main.post(()->{if(destroyed||!yummyFrame||!bridgeNonce.equals(nonce))return;webActuallyPlaying=active;if(active)playing=true;save(true);});}else if(kind.equals("time")){long now=SystemClock.elapsedRealtime();if(now-lastBridge<400)return;lastBridge=now;double t=j.optDouble("time",-1),d=j.optDouble("duration",-1);if(!Double.isFinite(t)||!Double.isFinite(d)||t<0||d<1||d>100000||t>d+5)return;boolean active=j.optBoolean("playing");YoruApp.app().main.post(()->{if(destroyed||!yummyFrame||!bridgeNonce.equals(nonce))return;browserTime=(int)t;browserDuration=(int)d;webActuallyPlaying=active;if(active)playing=true;save(false);});}else if(kind.equals("episode")){double ep=j.optDouble("episode",-1);if(ep<0||ep>100000||!Double.isFinite(ep))return;YoruApp.app().main.post(()->{if(destroyed||!yummyFrame||!bridgeNonce.equals(nonce))return;if(Math.abs(ep-wantedEpisode)>.001){wantedEpisode=ep;browserTime=0;browserDuration=0;if(playback!=null&&playback.video!=null)for(int i=0;i<playback.video.episodeList.size();i++){Anime.Episode found=playback.video.episodeList.get(i);if(Double.compare(found.number,ep)==0){episode=found;setup=true;episodeSelect.setSelection(i);setup=false;break;}}}status.setText("Iframe · YummyAnime · серия "+number(ep));});}else if(kind.equals("ended")){YoruApp.app().main.post(()->{if(!destroyed&&bridgeNonce.equals(nonce)&&playback!=null&&playback.video!=null&&YoruApp.app().autoNextAllowed())move(1);});}}catch(Exception ignored){}}}
    private void loadOffline(String id){save(true);stopMedia();Download d=YoruApp.app().downloads().get(id);if(d==null||d.state!=Download.STATE_COMPLETED){error("Эта серия ещё не скачана полностью.");return;}offlineId=id;offlineDownload=d;JSONObject m=DownloadHub.metadata(d);anime=Anime.from(m.optJSONObject("anime"));wantedEpisode=m.optDouble("episode",1);episode=new Anime.Episode();episode.number=wantedEpisode;episode.id=id;episode.name=m.optString("title","");quality=m.optInt("quality",0);dubbing=ApiRepository.downloadSourceName(Anime.from(m.optJSONObject("source")).source);title.setText(anime.title);seekMs=resumeFor(wantedEpisode);nativeMode=true;trustedKodik=false;currentUrl=d.request.uri.toString();video.setVisibility(View.VISIBLE);web.setVisibility(View.GONE);selectors.setVisibility(View.GONE);epRow.setVisibility(View.VISIBLE);sourceSelect.setEnabled(false);loading.setVisibility(View.VISIBLE);player.setTrackSelectionParameters(player.getTrackSelectionParameters().buildUpon().setMaxVideoSize(Integer.MAX_VALUE,Integer.MAX_VALUE).setForceLowestBitrate(false).build());player.setMediaSource(new DefaultMediaSourceFactory(YoruApp.app().mediaCache.offlineFactory()).createMediaSource(YoruApp.app().downloads().offlineItem(d)));player.prepare();player.play();prev.setEnabled(YoruApp.app().downloads().neighbour(d,-1)!=null);next.setEnabled(YoruApp.app().downloads().neighbour(d,1)!=null);prev.setAlpha(prev.isEnabled()?1:.4f);next.setAlpha(next.isEnabled()?1:.4f);status.setText("Офлайн · серия "+number(wantedEpisode));}
    private void updateNext(){if(playback==null||playback.video==null||episode==null)return;int i=playback.video.episodeList.indexOf(episode);prev.setEnabled(i>0);prev.setAlpha(i>0?1:.4f);next.setEnabled(i>=0&&i+1<playback.video.episodeList.size());next.setAlpha(next.isEnabled()?1:.4f);}
    private void move(int delta){if(offlineId!=null){Download next=YoruApp.app().downloads().neighbour(offlineDownload,delta);if(next!=null)loadOffline(next.request.id);else Ui.toast(this,"Следующая серия не скачана");return;}if(playback==null||playback.video==null||episode==null)return;int i=playback.video.episodeList.indexOf(episode)+delta;if(i>=0&&i<playback.video.episodeList.size()){save(true);seekMs=0;setup=true;episodeSelect.setSelection(i);setup=false;loadEpisode(playback.video.episodeList.get(i));}}
    private void error(String message){loading.setVisibility(View.GONE);status.setText(message);Ui.toast(this,message);}
    private void save(boolean force){if(!playing||anime==null)return;long now=System.currentTimeMillis();if(!force&&now-lastSaved<3500)return;lastSaved=now;if(nativeMode&&video!=null)YoruApp.app().store.progress(anime,wantedEpisode,(int)(player.getCurrentPosition()/1000),player.getDuration()==C.TIME_UNSET?0:(int)Math.max(0,player.getDuration()/1000),offlineId==null?"auto":"offline",dubbing,true);else if(trustedKodik)YoruApp.app().store.progress(anime,wantedEpisode,browserTime,browserDuration,playback!=null&&playback.directKodik?"kodik":mode,dubbing,true);}
    private void stopMedia(){playing=false;trustedKodik=false;yummyFrame=false;webActuallyPlaying=false;bridgeNonce="";if(video!=null){try{player.stop();player.clearMediaItems();}catch(Exception ignored){}}if(web!=null){web.removeJavascriptInterface("YoruPlayback");web.stopLoading();web.loadUrl("about:blank");}getWindow().clearFlags(WindowManager.LayoutParams.FLAG_KEEP_SCREEN_ON);}
